def _IOC(dir, type, nr, size):
    return (dir << 30) | (type << 8) | nr | (size << 16)
def _IOR(type, nr, size): return _IOC(2, ord(type), nr, size)
def _IOW(type, nr, size): return _IOC(1, ord(type), nr, size)

